UPDATE drink_details
SET deleted_at = NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh',
  deleted_by = #{deletedBy}
WHERE deleted_at IS NULL
AND drink_id IN (
  SELECT d.drink_id
  FROM drinks AS d
  WHERE d.drink_category_id = #{categoryId}
  AND d.is_deleted = FALSE
  
    
      
    
    
      AND d.shop_id = #{currentUserShopId}
    
    
      AND 1 = 0
    
  
)

UPDATE drinks
SET is_deleted = TRUE,
  deleted_at = NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh',
  deleted_by = #{deletedBy}
WHERE drink_category_id = #{categoryId}
AND is_deleted = FALSE

  
    
  
  
    AND shop_id = #{currentUserShopId}
  
  
    AND 1 = 0

    UPDATE drink_categories
    SET is_deleted = TRUE,
      deleted_at = NOW() AT TIME ZONE 'Asia/Ho_Chi_Minh',
      deleted_by = #{deletedBy}
    WHERE drink_category_id = #{categoryId}
    AND is_deleted = FALSE
    
      
      
        
      

      
      
        AND shop_id = #{currentUserShopId}
      
      
        AND 1 = 0
